public class Main {
    public static void main(String[] args) {
        String s = "hello";
        // toUpperCase cannot change s; it returns a brand new String
        String t = s.toUpperCase();
        System.out.println("original: " + s);
        System.out.println("upper copy: " + t);
        System.out.println("original after: " + s);
        // To edit one letter: copy into a char array, change it, make a new String
        char[] arr = s.toCharArray();
        arr[0] = 'j';
        System.out.println("edited via char array: " + new String(arr));
        // To build a long string, append into one StringBuilder
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 10; i++) sb.append(i);
        System.out.println("built: " + sb);
        // Time O(N) and space O(N) for a result of N characters
    }
}

