public class Main {
    public static void main(String[] args) {
        String a = "hello";                    // literal: lives in the string pool
        String b = new String("hel") + "lo";   // built at run time: a new object
        System.out.println("a = " + a + ", b = " + b);
        // equals compares the letters one by one
        System.out.println("same content: " + a.equals(b));
        // == asks "is this the very same object?"
        System.out.println("same object: " + (a == b));
        // intern() returns the pooled copy, which is the object a points to
        String c = b.intern();
        System.out.println("same object after intern: " + (a == c));
        // equals costs O(N) time for N letters; == costs O(1); space O(1)
    }
}

