// JavaScript string values have no visible identity, so we wrap them in
// String objects to see the difference between "same object" and "same letters".
const a = new String("hello");
const b = new String("hel" + "lo");
console.log("a = " + a + ", b = " + b);

// valueOf() gives the plain text; === on plain text compares the letters
console.log("same content: " + (a.valueOf() === b.valueOf()));

// === on two objects asks "is this the very same object?"
console.log("same object: " + (a === b));

// A tiny intern pool: one shared object per distinct text
const pool = new Map();
function intern(s) {
  const key = s.valueOf();
  if (!pool.has(key)) pool.set(key, s);
  return pool.get(key);
}
console.log("same object after intern: " + (intern(a) === intern(b)));
// Content check costs O(N) for N letters; identity check O(1); pool space O(total text)

