#include <bits/stdc++.h>
using namespace std;

unordered_set<string> pool;   // a tiny intern pool: one shared copy per text

// Returns the address of the single pooled copy of s
const string* intern(const string& s) {
    return &*pool.insert(s).first;
}

int main() {
    string a = "hello";
    string b = string("hel") + "lo";   // a second, separate object
    cout << "a = " << a << ", b = " << b << "\n";
    // == on std::string compares the letters (like equals in Java)
    cout << "same content: " << (a == b ? "true" : "false") << "\n";
    // comparing addresses asks "is this the very same object?"
    cout << "same object: " << (&a == &b ? "true" : "false") << "\n";
    // after interning, both names lead to the same pooled object
    cout << "same object after intern: " << (intern(a) == intern(b) ? "true" : "false") << "\n";
    // Content check O(N) for N letters; address check O(1); pool space O(total text)
    return 0;
}

