import java.util.*;

public class Main {
    public static void main(String[] args) {
        String s = "listen", t = "silent";
        System.out.println("s = " + s + ", t = " + t);
        // 26-slot array: slot 0 is 'a', slot 25 is 'z'
        int[] cs = new int[26], ct = new int[26];
        for (char c : s.toCharArray()) cs[c - 'a']++;
        for (char c : t.toCharArray()) ct[c - 'a']++;
        StringBuilder sb = new StringBuilder("counts of s:");
        for (int i = 0; i < 26; i++)
            if (cs[i] > 0) sb.append(" ").append((char) ('a' + i)).append("=").append(cs[i]);
        System.out.println(sb);
        // Comparing two count arrays is always 26 steps
        System.out.println("anagram (26-slot array): " + Arrays.equals(cs, ct));
        // Hash map: works for any character, but is slower per step
        Map<Character, Integer> map = new HashMap<>();
        for (char c : s.toCharArray()) map.merge(c, 1, Integer::sum);
        for (char c : t.toCharArray()) map.merge(c, -1, Integer::sum);
        boolean ok = true;
        for (int v : map.values()) if (v != 0) ok = false;
        System.out.println("anagram (hash map): " + ok);
        // Time O(N); space O(1) for the array, O(distinct characters) for the map
    }
}

