int main() {
    string s = "listen", t = "silent";
    cout << "s = " << s << ", t = " << t << "\n";
    // 26-slot array: slot 0 is 'a', slot 25 is 'z'
    array<int, 26> cs{}, ct{};
    for (char c : s) cs[c - 'a']++;
    for (char c : t) ct[c - 'a']++;
    cout << "counts of s:";
    for (int i = 0; i < 26; i++)
        if (cs[i] > 0) cout << " " << char('a' + i) << "=" << cs[i];
    cout << "\n";
    // Comparing two count arrays is always 26 steps
    cout << "anagram (26-slot array): " << (cs == ct ? "true" : "false") << "\n";
    // Hash map: works for any character, but is slower per step
    unordered_map<char, int> mp;
    for (char c : s) mp[c]++;
    for (char c : t) mp[c]--;
    bool ok = true;
    for (auto &p : mp) if (p.second != 0) ok = false;
    cout << "anagram (hash map): " << (ok ? "true" : "false") << "\n";
    // Time O(N); space O(1) for the array, O(distinct characters) for the map
    return 0;
}

