using System;
using System.Collections.Generic;
using System.Text;

class Program {
    static void Main() {
        string s = "listen", t = "silent";
        Console.WriteLine("s = " + s + ", t = " + t);
        // 26-slot array: slot 0 is 'a', slot 25 is 'z'
        int[] cs = new int[26], ct = new int[26];
        foreach (char c in s) cs[c - 'a']++;
        foreach (char c in t) ct[c - 'a']++;
        StringBuilder sb = new StringBuilder("counts of s:");
        for (int i = 0; i < 26; i++)
            if (cs[i] > 0) sb.Append(" ").Append((char)('a' + i)).Append("=").Append(cs[i]);
        Console.WriteLine(sb.ToString());
        // Comparing two count arrays is always 26 steps
        bool same = true;
        for (int i = 0; i < 26; i++) if (cs[i] != ct[i]) same = false;
        Console.WriteLine("anagram (26-slot array): " + (same ? "true" : "false"));
        // Hash map: works for any character, but is slower per step
        Dictionary<char, int> map = new Dictionary<char, int>();
        foreach (char c in s) { int v; map.TryGetValue(c, out v); map[c] = v + 1; }
        foreach (char c in t) { int v; map.TryGetValue(c, out v); map[c] = v - 1; }
        bool ok = true;
        foreach (int v in map.Values) if (v != 0) ok = false;
        Console.WriteLine("anagram (hash map): " + (ok ? "true" : "false"));
        // Time O(N); space O(1) for the array, O(distinct characters) for the map
    }
}

