public class Main {
    // Simulates n appends into a growing array and counts copied characters
    static long copies(int n, boolean doubling) {
        int cap = doubling ? 1 : 10, size = 0;
        long copied = 0;
        for (int i = 0; i < n; i++) {
            if (size == cap) {            // full: move everything to a bigger array
                copied += size;
                cap = doubling ? cap * 2 : cap + 10;
            }
            size++;                       // the append itself: one write
        }
        return copied;
    }

    public static void main(String[] args) {
        int n = 1000;
        System.out.println("appends: " + n);
        long a = copies(n, true), b = copies(n, false);
        // Doubling: copies are 1 + 2 + 4 + ... which stays below 2N
        System.out.println("doubling: copies = " + a + ", total work = " + (a + n));
        // +10: copies are 10 + 20 + 30 + ... which grows like N*N/20
        System.out.println("grow by +10: copies = " + b + ", total work = " + (b + n));
        // Doubling: O(N) total, O(1) amortized per append. +10: O(N^2) total. Space O(N).
    }
}

