public class Main {
    // Grows outwards from (l, r) while the two ends match; returns the length found
    static int expand(String s, int l, int r) {
        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { l--; r++; }
        return r - l - 1;   // l and r stopped one step outside the palindrome
    }

    public static void main(String[] args) {
        String s = "forgeeksskeegfor";
        int start = 0, best = 0;
        for (int c = 0; c < s.length(); c++) {
            int odd = expand(s, c, c);        // center is the letter c
            int even = expand(s, c, c + 1);   // center is the gap after c
            int len = Math.max(odd, even);
            if (len > best) {
                best = len;
                start = c - (len - 1) / 2;    // works for odd and even lengths
            }
        }
        System.out.println("s = " + s);
        System.out.println("longest palindrome: " + s.substring(start, start + best)
                + " (length " + best + ")");
        // Time O(N^2): 2N-1 centers, each can expand up to N. Space O(1).
    }
}

