code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String txt = "abracadabra", pat = "abra";
        long B = 31, M = 1_000_000_007L;
        int n = txt.length(), m = pat.length();
        long power = 1;                         // B^(m-1) mod M: weight of the leftmost letter
        for (int i = 1; i < m; i++) power = power * B % M;
        long hp = 0, hw = 0;                    // hash of pattern, hash of current window
        for (int i = 0; i < m; i++) {
            hp = (hp * B + (pat.charAt(i) - 'a' + 1)) % M;   // letters are 1..26, never 0
            hw = (hw * B + (txt.charAt(i) - 'a' + 1)) % M;
        }
        List<Integer> found = new ArrayList<>();
        for (int i = 0; i + m <= n; i++) {
            // equal hashes: check the letters to rule out a collision
            if (hw == hp && txt.startsWith(pat, i)) found.add(i);
            if (i + m < n) {
                long out = (txt.charAt(i) - 'a' + 1) * power % M;
                hw = ((hw - out + M) % M * B + (txt.charAt(i + m) - 'a' + 1)) % M;   // O(1) slide
            }
        }
        System.out.println("text = " + txt + ", pattern = " + pat);
        System.out.println("pattern hash = " + hp);
        System.out.println("matches at: " + found);
        // Expected time O(N + M), worst case O(N*M) with many collisions. Space O(1).
    }
}

