#include <bits/stdc++.h>
using namespace std;

int main() {
    string txt = "abracadabra", pat = "abra";
    long long B = 31, M = 1000000007LL;
    int n = txt.size(), m = pat.size();
    long long power = 1;                    // B^(m-1) mod M: weight of the leftmost letter
    for (int i = 1; i < m; i++) power = power * B % M;
    long long hp = 0, hw = 0;               // hash of pattern, hash of current window
    for (int i = 0; i < m; i++) {
        hp = (hp * B + (pat[i] - 'a' + 1)) % M;   // letters are 1..26, never 0
        hw = (hw * B + (txt[i] - 'a' + 1)) % M;
    }
    vector<int> found;
    for (int i = 0; i + m <= n; i++) {
        // equal hashes: check the letters to rule out a collision
        if (hw == hp && txt.compare(i, m, pat) == 0) found.push_back(i);
        if (i + m < n) {
            long long out = (txt[i] - 'a' + 1) * power % M;
            hw = ((hw - out + M) % M * B + (txt[i + m] - 'a' + 1)) % M;   // O(1) slide
        }
    }
    cout << "text = " << txt << ", pattern = " << pat << "\n";
    cout << "pattern hash = " << hp << "\n";
    cout << "matches at: [";
