using System;
using System.Collections.Generic;

class Program {
    static void Main() {
        string txt = "abracadabra", pat = "abra";
        long B = 31, M = 1000000007L;
        int n = txt.Length, m = pat.Length;
        long power = 1;                         // B^(m-1) mod M: weight of the leftmost letter
        for (int i = 1; i < m; i++) power = power * B % M;
        long hp = 0, hw = 0;                    // hash of pattern, hash of current window
        for (int i = 0; i < m; i++) {
            hp = (hp * B + (pat[i] - 'a' + 1)) % M;   // letters are 1..26, never 0
            hw = (hw * B + (txt[i] - 'a' + 1)) % M;
        }
        List<int> found = new List<int>();
        for (int i = 0; i + m <= n; i++) {
            // equal hashes: check the letters to rule out a collision
            if (hw == hp && string.CompareOrdinal(txt, i, pat, 0, m) == 0) found.Add(i);
            if (i + m < n) {
                long outv = (txt[i] - 'a' + 1) * power % M;
                hw = ((hw - outv + M) % M * B + (txt[i + m] - 'a' + 1)) % M;   // O(1) slide
            }
        }
        Console.WriteLine("text = " + txt + ", pattern = " + pat);
        Console.WriteLine("pattern hash = " + hp);
        Console.WriteLine("matches at: [" + string.Join(", ", found) + "]");
        // Expected time O(N + M), worst case O(N*M) with many collisions. Space O(1).
    }
}

