import java.util.*;

public class Main {
    // Polynomial hash of s with base b and modulus m (letters are 1..26)
    static long hash(String s, long b, long m) {
        long h = 0;
        for (char c : s.toCharArray()) h = (h * b + (c - 'a' + 1)) % m;
        return h;
    }

    // Number of pairs of different strings that share a key
    static long pairs(Map<Long, Integer> count) {
        long total = 0;
        for (int c : count.values()) total += (long) c * (c - 1) / 2;
        return total;
    }

    public static void main(String[] args) {
        String letters = "abcde";
        Map<Long, Integer> single = new HashMap<>(), dbl = new HashMap<>();
        int n = 0;
        // All 125 three-letter strings over a..e
        for (char x : letters.toCharArray())
            for (char y : letters.toCharArray())
                for (char z : letters.toCharArray()) {
                    String s = "" + x + y + z;
                    long h1 = hash(s, 31, 101), h2 = hash(s, 37, 103);
                    single.merge(h1, 1, Integer::sum);
                    dbl.merge(h1 * 103 + h2, 1, Integer::sum);   // pack both hashes in one key
                    n++;
                }
        System.out.println("strings hashed: " + n);
        System.out.println("single hash (mod 101): " + pairs(single) + " colliding pairs");
        System.out.println("double hash (mod 101 and mod 103): " + pairs(dbl) + " colliding pairs");
        // Time O(K * L) for K strings of length L; space O(K)
    }
}

