import java.util.*;

public class Main {
    static int[] buildLps(String pat) {
        int m = pat.length();
        int[] lps = new int[m];            // lps[0] is always 0
        int len = 0, i = 1;                // len = length of the current border
        while (i < m) {
            if (pat.charAt(i) == pat.charAt(len)) {
                lps[i++] = ++len;          // the border grows by one letter
            } else if (len > 0) {
                len = lps[len - 1];        // try the next shorter border, i stays
            } else {
                lps[i++] = 0;              // no border ends here
            }
        }
        return lps;
    }

    public static void main(String[] args) {
        String pat = "aabaaab";
        System.out.println("pattern = " + pat);
        System.out.println("lps = " + Arrays.toString(buildLps(pat)));
        // Time O(M): len rises at most M times, and each fallback lowers it. Space O(M).
    }
}

