import java.util.*;

public class Main {
    public static void main(String[] args) {
        String txt = "abababcabababab", pat = "abab";
        int n = txt.length(), m = pat.length();
        int[] lps = new int[m];
        for (int i = 1, len = 0; i < m; ) {          // build the LPS table
            if (pat.charAt(i) == pat.charAt(len)) lps[i++] = ++len;
            else if (len > 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        List<Integer> found = new ArrayList<>();
        int i = 0, j = 0, steps = 0;
        while (i < n) {
            steps++;                                  // one loop step
            if (txt.charAt(i) == pat.charAt(j)) {
                i++; j++;                             // both pointers move forward
                if (j == m) {
                    found.add(i - m);
                    j = lps[j - 1];                   // keep the overlap for the next match
                }
            } else if (j > 0) {
                j = lps[j - 1];                       // j falls back, i does not move
            } else {
                i++;                                  // nothing matched, move on
            }
        }
        System.out.println("text = " + txt + ", pattern = " + pat);
        System.out.println("matches at: " + found);
        System.out.println("loop steps: " + steps + " (limit 2N = " + 2 * n + ")");
        // Time O(N + M), space O(M) for the LPS table
    }
}

