import java.util.*;

public class Main {
    static int[] zArray(String s) {
        int n = s.length();
        int[] z = new int[n];
        int l = 0, r = 0;                      // box: s[l..r-1] equals a prefix of s
        for (int i = 1; i < n; i++) {
            // inside the box: copy the mirror value, but not past the box edge
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            // extend with real comparisons
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            // this match reaches further right: it becomes the new box
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    }

    public static void main(String[] args) {
        String pat = "aab", txt = "baabaaab";
        String s = pat + "$" + txt;            // '$' appears in neither string
        int[] z = zArray(s);
        List<Integer> found = new ArrayList<>();
        for (int i = pat.length() + 1; i < s.length(); i++)
            if (z[i] == pat.length()) found.add(i - pat.length() - 1);
        System.out.println("s = " + s);
        System.out.println("z = " + Arrays.toString(z));
        System.out.println("matches in text at: " + found);
        // Time O(N + M): every successful comparison moves r to the right. Space O(N + M).
    }
}

