import java.util.*;

public class Main {
    static final long B = 31, M = 1_000_000_007L;

    static long hash(String s) {
        long h = 0;
        for (char c : s.toCharArray()) h = (h * B + (c - 'a' + 1)) % M;
        return h;
    }

    public static void main(String[] args) {
        String txt = "abracadabra";
        String[] pats = {"abr", "cad", "dab"};
        int n = txt.length(), m = 3;
        // One hash-map entry per pattern: a window is checked against all of them in O(1)
        Map<Long, String> byHash = new HashMap<>();
        for (String p : pats) byHash.put(hash(p), p);
        long power = 1;
        for (int i = 1; i < m; i++) power = power * B % M;
        System.out.println("text = " + txt + ", patterns = " + String.join(" ", pats));
        long hw = hash(txt.substring(0, m));
        for (int i = 0; i + m <= n; i++) {
            String p = byHash.get(hw);
