public class Main {
    // KMP: first index of pat in txt, or -1. O(N + M) guaranteed.
    static int find(String txt, String pat) {
        int m = pat.length();
        int[] lps = new int[m];
        for (int i = 1, len = 0; i < m; ) {
            if (pat.charAt(i) == pat.charAt(len)) lps[i++] = ++len;
            else if (len > 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        for (int i = 0, j = 0; i < txt.length(); ) {
            if (txt.charAt(i) == pat.charAt(j)) {
                i++; j++;
                if (j == m) return i - m;
            } else if (j > 0) j = lps[j - 1];
            else i++;
        }
        return -1;
    }

    // Returns how many left shifts turn s into goal, or -1 if it is not a rotation
    static int rotation(String s, String goal) {
        if (s.length() != goal.length()) return -1;   // the length check is required
        if (s.isEmpty()) return 0;
        return find(s + s, goal);   // every rotation is a window of s + s
    }

    static void show(String s, String goal) {
        int k = rotation(s, goal);
        System.out.println(s + " -> " + goal + ": rotation = " + (k >= 0) + ", left shifts = " + k);
    }

    public static void main(String[] args) {
        show("waterbottle", "erbottlewat");
        show("abc", "ab");       // inside "abcabc", but the lengths differ
        show("abcd", "acbd");    // same letters, wrong order
        // Time O(N), space O(N) for s + s and the LPS table
    }
}

