import java.util.*;

public class Main {
    // All runs of k words in a row ("shingles"), kept as a set
    static Set<String> shingles(String doc, int k) {
        String[] w = doc.split(" ");
        Set<String> set = new HashSet<>();
        for (int i = 0; i + k <= w.length; i++)
            set.add(String.join(" ", Arrays.copyOfRange(w, i, i + k)));
        return set;
    }

    public static void main(String[] args) {
        String a = "the quick brown fox jumps over the lazy dog";
        String b = "the quick brown fox leaps over the lazy dog";
        int k = 3;
        Set<String> sa = shingles(a, k), sb = shingles(b, k);
        // shared = shingles that appear in both documents
        int shared = 0;
        for (String x : sa) if (sb.contains(x)) shared++;
        int total = sa.size() + sb.size() - shared;   // size of the union
        System.out.println("A: " + a);
        System.out.println("B: " + b);
        System.out.println("k = " + k + ", shingles in A = " + sa.size() + ", in B = " + sb.size());
        // Jaccard similarity = shared / total; close to 1 means near-duplicate
        System.out.println("shared = " + shared + ", total = " + total
                + ", Jaccard = " + shared + "/" + total);
        // Time O(L * k) here; a rolling hash makes it O(L). Space O(L).
        // Real systems store a 64-bit hash of each shingle, not the text.
    }
}

