// All runs of k words in a row ("shingles"), kept as a set
set<string> shingles(const string& doc, int k) {
    vector<string> w;
    stringstream ss(doc);
    string word;
    while (ss >> word) w.push_back(word);
    set<string> out;
    for (int i = 0; i + k <= (int)w.size(); i++) {
        string sh = w[i];
        for (int j = 1; j < k; j++) sh += " " + w[i + j];
        out.insert(sh);
    }
    return out;
}

