public class Main {
    static int seed = 12345;
    // Small repeatable random generator, so every run tests the same inputs
    static int next() { seed = (seed * 75 + 74) % 65537; return seed; }

    static String randomString(int len) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) sb.append((char) ('a' + next() % 2));   // only a and b
        return sb.toString();
    }

    // Reference: obviously correct, O(N*M)
    static int brute(String t, String p) {
        int count = 0;
        for (int i = 0; i + p.length() <= t.length(); i++)
            if (t.startsWith(p, i)) count++;
        return count;
    }

    // Code under review: KMP, O(N + M)
    static int kmp(String t, String p) {
        int m = p.length(), count = 0;
        int[] lps = new int[m];
        for (int i = 1, len = 0; i < m; ) {
            if (p.charAt(i) == p.charAt(len)) lps[i++] = ++len;
            else if (len > 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        for (int i = 0, j = 0; i < t.length(); ) {
            if (t.charAt(i) == p.charAt(j)) {
                i++; j++;
                if (j == m) { count++; j = lps[j - 1]; }   // keeps overlapping matches
            } else if (j > 0) j = lps[j - 1];
            else i++;
        }
        return count;
    }

    public static void main(String[] args) {
        int tests = 1000, bad = 0, total = 0;
        for (int k = 0; k < tests; k++) {
            String t = randomString(1 + next() % 12), p = randomString(1 + next() % 3);
            int want = brute(t, p), got = kmp(t, p);
            total += want;
            // on the first difference, print the small input that shows the bug
            if (want != got && bad++ == 0) System.out.println("FAIL: " + t + " / " + p);
        }
        System.out.println("tests: " + tests + ", matches counted: " + total + ", mismatches: " + bad);
        // Time O(tests * N * M) for the reference; space O(N)
    }
}

