int brute(const string& t, const string& p) {
    int count = 0;
    for (size_t i = 0; i + p.size() <= t.size(); i++)
        if (t.compare(i, p.size(), p) == 0) count++;
    return count;
}

// Code under review: KMP, O(N + M)
int kmp(const string& t, const string& p) {
    int m = p.size(), count = 0;
    vector<int> lps(m, 0);
    for (int i = 1, len = 0; i < m; ) {
        if (p[i] == p[len]) lps[i++] = ++len;
        else if (len > 0) len = lps[len - 1];
        else lps[i++] = 0;
    }
    for (int i = 0, j = 0; i < (int)t.size(); ) {
        if (t[i] == p[j]) {
            i++; j++;
            if (j == m) { count++; j = lps[j - 1]; }   // keeps overlapping matches
        } else if (j > 0) j = lps[j - 1];
        else i++;
    }
    return count;
}

int main() {
    int tests = 1000, bad = 0, total = 0;
    for (int k = 0; k < tests; k++) {
        string t = randomString(1 + nextRand() % 12);
        string p = randomString(1 + nextRand() % 3);
        int want = brute(t, p), got = kmp(t, p);
        total += want;
        // on the first difference, print the small input that shows the bug
        if (want != got && bad++ == 0) cout << "FAIL: " << t << " / " << p << "\n";
    }
    cout << "tests: " << tests << ", matches counted: " << total << ", mismatches: " << bad << "\n";
    // Time O(tests * N * M) for the reference; space O(N)
    return 0;
}

